import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import os

# Plotting script generated by Claude.

# ── style ──────────────────────────────────────────────────────────────────
sns.set_theme(style="whitegrid", palette="colorblind")
RESULTS_DIR = os.path.dirname(os.path.abspath(__file__))
PLOTS_DIR   = os.path.join(RESULTS_DIR, "plots")
os.makedirs(PLOTS_DIR, exist_ok=True)

THREADS = [1, 2, 4, 8, 14, 16]

# ── helpers ────────────────────────────────────────────────────────────────
def load(filename):
    path = os.path.join(RESULTS_DIR, filename)
    df   = pd.read_csv(path)
    df.columns = df.columns.str.strip()
    # ensure chunk is string for consistent filtering
    df["chunk"] = df["chunk"].astype(str)
    return df

def save(fig, name):
    path = os.path.join(PLOTS_DIR, name)
    fig.savefig(path, dpi=150, bbox_inches="tight")
    plt.close(fig)
    print(f"Saved: {name}")

# ── 1. Speedup char n-gram ─────────────────────────────────────────────────
def plot_char_speedup(df, corpus_label):
    fig, ax = plt.subplots(figsize=(8, 5))

    for n, label in [(2, "Bigram"), (3, "Trigram")]:
        sub = df[(df["type"] == "char") & (df["n"] == n)]
        ax.plot(sub["threads"], sub["speedup"], marker="o", label=label)

    ax.set_title(f"Char n-gram speedup vs thread count ({corpus_label})")
    ax.set_xlabel("Threads")
    ax.set_ylabel("Speedup")
    ax.set_xticks(THREADS)
    ax.legend()
    save(fig, f"speedup_char_{corpus_label}.png")

# ── 2. Speedup word — scheduling comparison ────────────────────────────────
def plot_word_scheduling(df, corpus_label):
    for n, label in [(2, "bigram"), (3, "trigram")]:
        fig, ax = plt.subplots(figsize=(8, 5))

        for sched in ["static", "dynamic", "guided"]:
            sub = df[
                (df["type"]     == "word") &
                (df["n"]        == n)      &
                (df["schedule"] == sched)  &
                (df["chunk"]    == "auto")
            ]
            ax.plot(sub["threads"], sub["speedup"], marker="o", label=sched)

        ax.set_title(f"Word {label} speedup — scheduling comparison ({corpus_label})")
        ax.set_xlabel("Threads")
        ax.set_ylabel("Speedup")
        ax.set_xticks(THREADS)
        ax.legend()
        save(fig, f"speedup_word_scheduling_{label}_{corpus_label}.png")

# ── 3. Speedup word — chunk size comparison ────────────────────────────────
def plot_word_chunksize(df, corpus_label):
    for sched in ["static", "dynamic"]:
        for n, label in [(2, "bigram"), (3, "trigram")]:
            fig, ax = plt.subplots(figsize=(8, 5))

            for chunk in ["auto", "64", "512", "4096"]:
                sub = df[
                    (df["type"]     == "word")  &
                    (df["n"]        == n)        &
                    (df["schedule"] == sched)    &
                    (df["chunk"]    == chunk)
                ]
                if not sub.empty:
                    ax.plot(sub["threads"], sub["speedup"], marker="o",
                            label=f"chunk={chunk}")

            ax.set_title(f"Word {label} speedup — {sched} chunk size ({corpus_label})")
            ax.set_xlabel("Threads")
            ax.set_ylabel("Speedup")
            ax.set_xticks(THREADS)
            ax.legend()
            save(fig, f"speedup_word_chunk_{sched}_{label}_{corpus_label}.png")

# ── 4. Speedup char vs word ────────────────────────────────────────────────
def plot_char_vs_word(df, corpus_label):
    for n, label in [(2, "bigram"), (3, "trigram")]:
        fig, ax = plt.subplots(figsize=(8, 5))

        char_sub = df[(df["type"] == "char") & (df["n"] == n)]
        ax.plot(char_sub["threads"], char_sub["speedup"],
                marker="o", label="Char n-gram")

        word_sub = df[
            (df["type"]     == "word")   &
            (df["n"]        == n)        &
            (df["schedule"] == "static") &
            (df["chunk"]    == "auto")
        ]
        ax.plot(word_sub["threads"], word_sub["speedup"],
                marker="o", label="Word n-gram (static, auto)")

        ax.set_title(f"Char vs Word {label} speedup ({corpus_label})")
        ax.set_xlabel("Threads")
        ax.set_ylabel("Speedup")
        ax.set_xticks(THREADS)
        ax.legend()
        save(fig, f"speedup_char_vs_word_{label}_{corpus_label}.png")

# ── 5. CPU time word — chunk size comparison ───────────────────────────────
def plot_cpu_time_word(df, corpus_label):
    for sched in ["static", "dynamic"]:
        for n, label in [(2, "bigram"), (3, "trigram")]:
            fig, ax = plt.subplots(figsize=(8, 5))

            for chunk in ["auto", "64", "512", "4096"]:
                sub = df[
                    (df["type"]     == "word")  &
                    (df["n"]        == n)        &
                    (df["schedule"] == sched)    &
                    (df["chunk"]    == chunk)
                ]
                if not sub.empty:
                    ax.plot(sub["threads"], sub["cpu_mean"], marker="o",
                            label=f"chunk={chunk}")

            ax.set_title(f"Word {label} CPU time — {sched} ({corpus_label})")
            ax.set_xlabel("Threads")
            ax.set_ylabel("CPU time (s)")
            ax.set_xticks(THREADS)
            ax.legend()
            save(fig, f"cpu_time_word_{sched}_{label}_{corpus_label}.png")

# ── 6. CPU time char ───────────────────────────────────────────────────────
def plot_cpu_time_char(df, corpus_label):
    for n, label in [(2, "bigram"), (3, "trigram")]:
        fig, ax = plt.subplots(figsize=(8, 5))

        sub = df[(df["type"] == "char") & (df["n"] == n)]
        ax.plot(sub["threads"], sub["cpu_mean"], marker="o", color="steelblue")

        ax.set_title(f"Char {label} CPU time ({corpus_label})")
        ax.set_xlabel("Threads")
        ax.set_ylabel("CPU time (s)")
        ax.set_xticks(THREADS)
        save(fig, f"cpu_time_char_{label}_{corpus_label}.png")

# ── 7. Corpus size comparison ──────────────────────────────────────────────
def plot_corpus_comparison(df_small, df_large, small_label, large_label):
    configs = [
        ("char", 2, "static", "auto", "char_bigram"),
        ("char", 3, "static", "auto", "char_trigram"),
        ("word", 2, "static", "auto", "word_bigram"),
        ("word", 3, "static", "auto", "word_trigram"),
    ]

    for typ, n, sched, chunk, name in configs:
        fig, ax = plt.subplots(figsize=(8, 5))

        for df, corpus_label in [(df_small, small_label), (df_large, large_label)]:
            sub = df[
                (df["type"]     == typ)   &
                (df["n"]        == n)     &
                (df["schedule"] == sched) &
                (df["chunk"]    == chunk)
            ]
            ax.plot(sub["threads"], sub["speedup"],
                    marker="o", label=corpus_label)

        ax.set_title(f"{name.replace('_', ' ').title()} — corpus size comparison")
        ax.set_xlabel("Threads")
        ax.set_ylabel("Speedup")
        ax.set_xticks(THREADS)
        ax.legend()
        save(fig, f"corpus_comparison_{name}.png")

# ── main ───────────────────────────────────────────────────────────────────
if __name__ == "__main__":
    # single corpus plots
    for csv_file, corpus_label in [("benchmark_x200.csv", "x200"),
                                    ("benchmark_x700.csv", "x700")]:
        path = os.path.join(RESULTS_DIR, csv_file)
        if not os.path.exists(path):
            print(f"Skipping {csv_file} — file not found")
            continue

        print(f"\nGenerating plots for {corpus_label}...")
        df = load(csv_file)

        plot_char_speedup(df, corpus_label)
        plot_word_scheduling(df, corpus_label)
        plot_word_chunksize(df, corpus_label)
        plot_char_vs_word(df, corpus_label)
        plot_cpu_time_char(df, corpus_label)
        plot_cpu_time_word(df, corpus_label)

    # corpus comparison plots
    small_path = os.path.join(RESULTS_DIR, "benchmark_x200.csv")
    large_path = os.path.join(RESULTS_DIR, "benchmark_x700.csv")
    if os.path.exists(small_path) and os.path.exists(large_path):
        print("\nGenerating corpus comparison plots...")
        df_small = load("benchmark_x200.csv")
        df_large = load("benchmark_x700.csv")
        plot_corpus_comparison(df_small, df_large, "x200", "x700")
